import { RouterProvider, createRouter } from "@tanstack/react-router";
import { routeTree } from "./routeTree.gen";

const router = createRouter({ routeTree });

function App() {
  return <RouterProvider router={router} />;
}

import {
  createRootRoute,
  createRoute,
  createRouter,
} from "@tanstack/react-router";

const rootRoute = createRootRoute();

const userRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/users/$userId",
  loader: ({ params }) =>
    fetch(`/api/users/${params.userId}`).then((r) => r.json()),
  component: UserDetail,
});

const routeTree = rootRoute.addChildren([userRoute]);

export const router = createRouter({ routeTree });

// Fully typed: params.userId is known to exist
function UserDetail() {
  const { userId } = userRoute.useParams();
  const user = userRoute.useLoaderData();

  return <h1>{user.name} ({userId})</h1>;
}

import { z } from "zod";

const productRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/products",
  validateSearch: z.object({
    page: z.number().int().min(1).default(1),
    sort: z.enum(["price", "rating"]).default("rating"),
  }),
  component: Products,
});

function Products() {
  const { page, sort } = productRoute.useSearch();

  return <p>Page {page}, sorted by {sort}</p>;
}
